package br.com.fiap.bank.plataforma.infrastructure.persistence;
import br.com.fiap.bank.plataforma.domain.*; import org.springframework.stereotype.Repository; import java.util.*; @Repository public class SolicitacaoCreditoRepositoryAdapter implements SolicitacaoCreditoRepository { private final SpringDataSolicitacaoRepository db; public SolicitacaoCreditoRepositoryAdapter(SpringDataSolicitacaoRepository db){this.db=db;} private SolicitacaoCredito toDomain(SolicitacaoCreditoJpaEntity e){return new SolicitacaoCredito(e.id,e.cpfCliente,e.nomeCliente,e.tipoCredito,e.valorSolicitado,e.quantidadeParcelas,e.rendaMensal,e.scoreCredito,e.status,e.parecerOperador,e.scrRestricoes,e.scoreBureau,e.dataSolicitacao,e.dataAtualizacao);} private SolicitacaoCreditoJpaEntity toEntity(SolicitacaoCredito x){var e=new SolicitacaoCreditoJpaEntity();e.id=x.getId();e.cpfCliente=x.getCpfCliente();e.nomeCliente=x.getNomeCliente();e.tipoCredito=x.getTipoCredito();e.valorSolicitado=x.getValorSolicitado();e.quantidadeParcelas=x.getQuantidadeParcelas();e.rendaMensal=x.getRendaMensal();e.scoreCredito=x.getScoreCredito();e.status=x.getStatus();e.parecerOperador=x.getParecerOperador();e.scrRestricoes=x.getScrRestricoes();e.scoreBureau=x.getScoreBureau();e.dataSolicitacao=x.getDataSolicitacao();e.dataAtualizacao=x.getDataAtualizacao();return e;} public SolicitacaoCredito save(SolicitacaoCredito x){return toDomain(db.save(toEntity(x)));} public Optional<SolicitacaoCredito> findById(Long id){return db.findById(id).map(this::toDomain);} public List<SolicitacaoCredito> findAll(){return db.findAllByOrderByDataSolicitacaoDesc().stream().map(this::toDomain).toList();} public List<SolicitacaoCredito> findByCpf(String cpf){return db.findByCpfClienteOrderByDataSolicitacaoDesc(cpf).stream().map(this::toDomain).toList();} }
